import SettingsShell from "./components/SettingsShell";

/**
 * Shared 67router settings layout (sub-nav + 760 px content column). A template, not the
 * section layout: `layout.tsx` here is generated by scripts/i18n/generate-route-namespaces.mjs
 * and rewritten on every run. A segment's template is not remounted when navigating between
 * its child pages, so the sub-nav persists like a layout would.
 */
export default function SettingsTemplate({ children }: { children: React.ReactNode }) {
  return <SettingsShell>{children}</SettingsShell>;
}
